insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-114', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Comparing $\kappa$ and $\Lambda_m$ as a strong electrolyte is diluted, the typical pattern is that', '["$\\kappa$ decreases while $\\Lambda_m$ increases","both $\\kappa$ and $\\Lambda_m$ fall sharply","both $\\kappa$ and $\\Lambda_m$ rise equally","$\\Lambda_m$ falls while $\\kappa$ stays constant"]'::jsonb, 0, 'Fewer ions per cm$^3$ lower $\kappa$, but each mole of electrolyte contributes more free ionic mobility, so $\Lambda_m$ rises.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'conductance') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
