insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-142', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'If $E^\circ(\mathrm{Cu^{2+}/Cu}) = +0.34\ \mathrm{V}$ and $E^\circ(\mathrm{Zn^{2+}/Zn}) = -0.76\ \mathrm{V}$, $E^\circ$ of the Daniell cell is', '["$1.10\\ \\mathrm{V}$","$0.42\\ \\mathrm{V}$","$-1.10\\ \\mathrm{V}$","$0.34\\ \\mathrm{V}$"]'::jsonb, 0, '$E^\circ_{\mathrm{cell}} = 0.34 - (-0.76) = 1.10\ \mathrm{V}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'cells-emf') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
