insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-147', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'In an electrolytic cell, as opposed to a galvanic cell, the anode is', '["the positive electrode, still the site of oxidation","the negative electrode, the site of reduction","always made of zinc","unnecessary if a salt bridge is present"]'::jsonb, 0, 'Oxidation is always anodic. An external source makes the electrolytic anode positive, whereas a galvanic anode is negative.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'cells-emf') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
