insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-148', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'A large positive $E^\circ_{\mathrm{cell}}$ corresponds to', '["a large equilibrium constant for the cell reaction","a vanishingly small $K$","$K$ exactly equal to 1","no relation at all to $K$"]'::jsonb, 0, '$\Delta G^\circ = -RT\ln K = -nFE^\circ$, so a sizable positive $E^\circ$ means $K \gg 1$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'cells-emf') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
