insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-149', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'For Zn–Cu with $E^\circ = 1.10\ \mathrm{V}$ and $n = 2$, $\Delta G^\circ$ is nearest ($F = 96500\ \mathrm{C\ mol^{-1}}$)', '["$-212\\ \\mathrm{kJ\\ mol^{-1}}$","$-106\\ \\mathrm{kJ\\ mol^{-1}}$","$+212\\ \\mathrm{kJ\\ mol^{-1}}$","$-1.10\\ \\mathrm{kJ\\ mol^{-1}}$"]'::jsonb, 0, '$\Delta G^\circ = -2 \times 96500 \times 1.10 = -212300\ \mathrm{J\ mol^{-1}} \approx -212\ \mathrm{kJ\ mol^{-1}}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'cells-emf') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
